async function ubermind_gateway_status(params,userSettings){
  try{
    if(!userSettings.gatewayUrl||!userSettings.gatewayToken)throw new Error('UberMind gateway settings are required');
    const base=userSettings.gatewayUrl.replace(/\/$/,'');
    const r=await fetch(base+'/api/ubermind/v1/status',{headers:{Authorization:'Bearer '+userSettings.gatewayToken,Accept:'application/json'}});
    const body=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error('Gateway status '+r.status+': '+(body.status||'request refused'));
    return body;
  }catch(error){return {ok:false,status:'UBERMIND_PLUGIN_STATUS_FAILED',error:String(error?.message||error)};}
}

async function ubermind_plan_task(params,userSettings){
  try{
    if(!userSettings.gatewayUrl||!userSettings.gatewayToken)throw new Error('UberMind gateway settings are required');
    const base=userSettings.gatewayUrl.replace(/\/$/,'');
    const task={
      schemaVersion:'uberbond.ubermind.cockpit-task.v1',
      taskId:params.taskId,
      taskClass:params.taskClass,
      qualityClass:params.qualityClass,
      sideEffectClass:'NONE',
      stakes:params.stakes,
      exact:params.exact===true,
      jevEligible:params.jevEligible===true,
      equivalenceClass:params.equivalenceClass||undefined,
      proofVerified:params.proofVerified===true,
      dependenciesCurrent:params.dependenciesCurrent===true,
      compositionVerified:params.compositionVerified!==false,
      preparationAllowed:params.preparationAllowed!==false,
      estimatedInputTokens:Number.isSafeInteger(params.estimatedInputTokens)?params.estimatedInputTokens:undefined,
      estimatedCachedInputTokens:Number.isSafeInteger(params.estimatedCachedInputTokens)?params.estimatedCachedInputTokens:undefined,
      maxOutputTokens:Number.isSafeInteger(params.maxOutputTokens)?params.maxOutputTokens:undefined
    };
    const r=await fetch(base+'/api/ubermind/v1/plan',{method:'POST',headers:{Authorization:'Bearer '+userSettings.gatewayToken,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(task)});
    const body=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error('Gateway plan '+r.status+': '+(body.status||'request refused'));
    return body;
  }catch(error){return {ok:false,status:'UBERMIND_PLUGIN_PLAN_FAILED',error:String(error?.message||error)};}
}
